 // FASE 1: estado pedagógico aditivo; as três chaves v1 continuam intactas.
 const lk='meuenem.enem.2027.learning.v2',CONF={certeza:'Certeza',duvida:'Dúvida',chute:'Chute'},ERRORS={conteudo:'Conteúdo',interpretacao:'Interpretação',distracao:'Distração'},INTERVALS=[1,3,7,15];
 const blankLearning=()=>({schema:2,migrated:false,reviews:{},diagnostics:{},history:[]});
 function validKey(k){return /^(matematica|linguagens|natureza|humanas):[LHMN]\d{3,4}$/.test(k)}
 function cleanLearning(x){const y=blankLearning();if(!x||typeof x!=='object')return y;y.migrated=!!x.migrated;for(const[k,v]of Object.entries(x.reviews||{})){if(validKey(k)&&v&&Number.isFinite(v.dueAt)&&Number.isFinite(v.stage)&&v.stage>=0&&v.stage<=3)y.reviews[k]={active:!!v.active,stage:Math.floor(v.stage),dueAt:v.dueAt,reason:v.reason==='chute'?'chute':'erro',createdAt:Number(v.createdAt)||Date.now(),lastReviewedAt:Number(v.lastReviewedAt)||null}}for(const[k,v]of Object.entries(x.diagnostics||{})){if(k.length<500&&v&&typeof v==='object')y.diagnostics[k]={topicKey:k,ids:Array.isArray(v.ids)?v.ids.filter(id=>/^[LHMN]\d{3,4}$/.test(id)).slice(0,5):[],completedAt:Number(v.completedAt)||null,dismissedAt:Number(v.dismissedAt)||null,total:Math.max(0,Math.min(5,Number(v.total)||0)),correct:Math.max(0,Math.min(5,Number(v.correct)||0)),secure:Math.max(0,Math.min(5,Number(v.secure)||0))}}y.history=(Array.isArray(x.history)?x.history:[]).filter(v=>v&&validKey(v.questionKey)&&Number.isFinite(v.at)&&['A','B','C','D','E'].includes(v.choice)).slice(-6000).map(v=>({questionKey:v.questionKey,at:v.at,choice:v.choice,correct:!!v.correct,confidence:CONF[v.confidence]?v.confidence:null,errorType:ERRORS[v.errorType]?v.errorType:null,context:['review','diagnostic','simulado'].includes(v.context)?v.context:'practice',sessionId:typeof v.sessionId==='string'?v.sessionId.slice(0,100):null}));return y}
 let learning=cleanLearning(load(lk,null));state.pending=null;state.reviewKey=null;state.reviewFilter='due';state.videoSubject='';state.videoSearch='';state.diagnostic=null;state.lastDiagnostic=null;state.resumeKey=null;
 function plusDays(at,n){const d=new Date(at);d.setDate(d.getDate()+n);return d.getTime()}
 function dayEnd(){const d=new Date();d.setHours(23,59,59,999);return d.getTime()}
 const getQ=k=>{const[a,id]=k.split(':');return (BANKS[a]||[]).find(q=>q.id===id)},topicKey=(a,s,t)=>[a,s,t].join('|');
 function persistLearning(){save(lk,learning)}
 function migrateLearning(){if(learning.migrated)return;for(const q of all()){const r=record(q);if(r?.choice&&!annul(q)&&r.choice!==q.answer&&!learning.reviews[key(q)])learning.reviews[key(q)]={active:true,stage:0,dueAt:plusDays(Number(r.updatedAt)||Date.now(),1),createdAt:Number(r.updatedAt)||Date.now(),reason:'erro',lastReviewedAt:null}}learning.migrated=true;persistLearning()}
 function reviewItems(){return Object.entries(learning.reviews).map(([k,r])=>({q:getQ(k),r,k})).filter(x=>x.q&&ready(x.q.area)&&!annul(x.q)).sort((a,b)=>a.r.dueAt-b.r.dueAt)}
 const dueReviews=()=>reviewItems().filter(x=>x.r.active&&x.r.dueAt<=dayEnd());
 const datePT=at=>new Date(at).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'});
 function scheduleAnswer(q,r,context){const k=key(q),prior=learning.reviews[k],now=r.updatedAt;if(r.choice!==q.answer||r.confidence==='chute'){learning.reviews[k]={active:true,stage:0,dueAt:plusDays(now,1),createdAt:now,reason:r.choice!==q.answer?'erro':'chute',lastReviewedAt:context==='review'?now:null}}else if(context==='review'&&prior?.active){if(prior.stage===3){prior.active=false;prior.lastReviewedAt=now}else{prior.stage++;prior.dueAt=plusDays(now,INTERVALS[prior.stage]);prior.lastReviewedAt=now}}learning.history.push({questionKey:k,at:now,choice:r.choice,correct:r.choice===q.answer,confidence:r.confidence,errorType:null,context,sessionId:state.diagnostic?.id||null});learning.history=learning.history.slice(-6000);persistLearning()}
 function youtubeURL(q){return 'https://www.youtube.com/results?search_query='+encodeURIComponent('ENEM '+q.year+' questão '+q.number+' '+q.subject+' resolução')}
