 function confidenceHTML(q){const p=state.pending;if(!p||p.questionKey!==key(q))return '<p class="muted">Primeiro escolha A–E. Depois indique sua confiança antes de conferir.</p>';return '<section class="confidence-panel" aria-label="Sua confiança antes do gabarito"><span class="eyebrow">ANTES DE CONFERIR</span><h3>Como você chegou à alternativa '+p.choice+'?</h3><p>Não muda a nota: ajuda você a saber o que revisar.</p><div class="confidence-options">'+Object.entries(CONF).map(([id,label])=>'<button type="button" data-confidence="'+id+'" class="confidence-choice '+(p.confidence===id?'selected':'')+'" aria-pressed="'+(p.confidence===id)+'"><b>'+label+'</b><small>'+({certeza:'Sei explicar o raciocínio',duvida:'Fiquei entre alternativas',chute:'Não soube justificar'}[id])+'</small></button>').join('')+'</div>'+btn('Conferir resposta','confirm-answer','primary',p.confidence?'':'disabled')+'</section>'}
