 function p3Schedule(){if(!p3Plan.profile)return{slots:[],warnings:[]};if(p3ScheduleCache)return p3ScheduleCache;const result=p3BaseSchedule(p3Plan.profile);result.slots=result.slots.map(s=>{const done=p3Plan.done[s.id],override=p3Plan.overrides[s.id];return done?.snapshot?{...done.snapshot,completed:true}:override?{...s,...override,id:s.id,date:s.date}:s});result.slots.sort((a,b)=>a.date.localeCompare(b.date)||a.start-b.start);p3ScheduleCache=result;return result}
 function p3Segments(s){if(s.kind==='break')return[{start:s.start,end:s.end,title:'Pausa — levante, descanse os olhos e volte sem culpa.',type:'break'}];if(s.customTitle)return[{start:s.start,end:s.end,title:s.customTitle,type:s.suggestionId&&!s.manual?'questions':'custom'}];if(s.kind==='redacao')return[{start:s.start,end:s.end,title:'Escrever / continuar / revisar a redação do tema da semana. Correção no chat do ENEM.',type:'redacao'}];const len=s.end-s.start,review=s.sequence%5===4,lesson=s.sequence%4===0,theory=lesson?Math.min(10,Math.floor(len*.4)):0,m=p3Method(s.subject,s.area),teacher=p3Teacher(s.subject,s.area),rows=[];let at=s.start;if(theory){rows.push({start:at,end:at+theory,title:'Videoaula orientada · '+(teacher?.name||'canal da matéria')+' · '+theory+' min reservados',type:'video',teacher});at+=theory}rows.push({start:at,end:s.end,title:(review?'Recuperação sem consulta + revisar erros + questões':p3Phase(s.date)==='Revisão'?'Questões intercaladas + justificar e corrigir':'Resolver questões + explicar o raciocínio')+' · meta flexível: '+Math.max(1,Math.floor((s.end-at)/5))+' itens',type:review?'review':'questions',method:m.title});return rows}
 function p3MakeSuggestions(rows,source){const groups=p3Groups(rows,r=>topicKey(r.area,r.subject,r.topic)).filter(g=>g.answered>=3&&g.answeredPct<60).sort((a,b)=>a.answeredPct-b.answeredPct).slice(0,3);for(const g of groups){const t=p3Topics.find(t=>t.key===g.label);if(!t||p3Plan.suggestions.some(x=>x.topicKey===t.key&&x.source===source))continue;const relevant=rows.filter(r=>topicKey(r.area,r.subject,r.topic)===t.key&&r.choice&&r.choice!==r.answer),types=Object.entries(ERRORS).map(([id])=>[id,relevant.filter(r=>r.errorType===id).length]).sort((a,b)=>b[1]-a[1]);p3Plan.suggestions.push({id:'P'+Date.now().toString(36)+'-'+p3Plan.suggestions.length,topicKey:t.key,source,status:'pending',createdAt:Date.now(),evidence:g.correct+'/'+g.answered+' respostas corretas nesta amostra',errorType:types[0]?.[1]?types[0][0]:null})}p3Plan.suggestions=p3Plan.suggestions.slice(-30);p3PersistPlan()}
