 function p3UndoSuggestion(id){const event=p3Plan.accepted.find(e=>e.id===id);if(!event)return;for(const c of event.changes){if(p3Plan.overrides[c.id]?.suggestionId===id&&!p3Plan.done[c.id]&&!p3Plan.overrides[c.id].manual){if(c.oldOverride)p3Plan.overrides[c.id]=c.oldOverride;else delete p3Plan.overrides[c.id]}}const s=p3Plan.suggestions.find(s=>s.id===id);if(s)s.status='undone';p3PersistPlan()}
 function p3BackupData(){return{schema:1,simulados:p3Sim,plano:p3Plan}}
 function p3ImportBackup(x){if(!x)return;if(x.schema!==1||!Array.isArray(x.simulados?.sessions))throw Error('Fase 3 inválida');const sims=x.simulados.sessions.map(p3CleanSession).filter(Boolean).slice(-P3_MAX),plan=p3CleanPlan(x.plano);p3Pause();p3Sim={schema:1,sessions:sims};p3Plan=plan;state.simId=null;p3Persist();p3PersistPlan()}

 // FASE 3A — interface: simulados, resultados, plano e métodos.
 const p3Button=(text,action,attrs='',primary=false)=>'<button type="button" class="btn '+(primary?'primary':'secondary')+'" data-p3="'+action+'" '+attrs+'>'+text+'</button>';
 const p3AreaName=a=>AREAS.find(x=>x.id===a)?.name||a;
 const p3Header=(title,description)=>'<div class="app-topbar"><span>Meu ENEM <b>/ '+esc(title)+'</b></span><span class="top-pill">ENEM 2027</span></div><header class="page-heading p3-heading"><div><span class="eyebrow">SEU TEMPO, SUA APRENDIZAGEM</span><h1>'+esc(title)+'</h1><p>'+description+'</p></div></header>'+(!storageOK?'<aside class="native-warning">O salvamento está indisponível. Exporte um backup antes de sair desta página.</aside>':'');
 function p3MethodHTML(subject,area,open=false){const m=p3Method(subject,area);return '<details class="p3-method panel" '+(open?'open':'')+'><summary><span><b>'+esc(subject)+'</b> · '+esc(m.title)+'</span><span>Como fazer ↓</span></summary><ol>'+m.steps.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ol><p class="method-note">'+esc(m.why)+'</p><p class="p3-practice-first"><b>Prática primeiro:</b> use resumo apenas para destravar uma dúvida. Termine a sessão resolvendo e justificando questões.</p><button class="btn secondary" type="button" data-view="methods">Ver evidências e métodos</button></details>'}
 function p3Availability(){const tri=$('#p3-sim-tri')?.value||'';let total=0;$$('.p3-subject-row').forEach(row=>{const info=p3Subjects.find(s=>s.key===row.dataset.subjectKey),topics=Array.from(row.querySelector('[data-sim-topics]').selectedOptions).map(x=>x.value),available=p3Pool({...info,topics},tri,v3BuilderYears(false)).length;row.querySelector('[data-available]').textContent=available+' disponíveis';if(row.querySelector('[data-sim-check]').checked)total+=Number(row.querySelector('[data-sim-count]').value)||0;row.classList.toggle('is-selected',row.querySelector('[data-sim-check]').checked)});if($('#p3-sim-total'))$('#p3-sim-total').textContent=total+' selecionadas · máximo 180'}
 function p3RenderSimulators(){const sessions=p3Sim.sessions.slice().reverse(),years=[...new Set(p3Eligible().map(q=>q.year))].sort((a,b)=>b-a);$('#main').innerHTML=p3Header('Simulados','Crie seu treino com as questões das apostilas. Sem ranking, sem pontos e sem IA.')+'<section class="panel p3-preset-panel"><h2>Prontos para começar</h2><div class="p3-preset-controls"><label class="field"><span>Área</span><select id="p3-preset-area">'+AREAS.filter(a=>a.id!=='redacao').map(a=>'<option value="'+a.id+'">'+a.name+'</option>').join('')+'</select></label><div class="button-row">'+p3Button('Área · 45 questões','preset','data-kind="area"')+p3Button('Mini · 10','preset','data-kind="mini10"')+p3Button('Mini · 20','preset','data-kind="mini20"')+'</div><label class="field"><span>Prova disponível por ano</span><select id="p3-preset-year">'+years.map(y=>'<option>'+y+'</option>').join('')+'</select></label>'+p3Button('Conferir prova do ano','preset','data-kind="year"')+'</div><p class="method-note">Confira quantidade e duração antes de iniciar. A prova por ano usa apenas o banco daquele ano, sem anuladas; 2006–2008 têm itens interdisciplinares sem repetição. Não há redação dentro do cronômetro.</p><div id="p3-preset-confirm"></div></section><section class="panel"><h2>Criar meu simulado</h2><p>Selecione matérias, assuntos e quantidade por matéria. Assuntos sem seleção = todos daquela matéria. A geração nunca completa silenciosamente com outro filtro.</p><form id="p3-builder"><div class="p3-form-grid"><label class="field"><span>Nome do treino</span><input id="p3-sim-title" maxlength="100" value="Meu treino de hoje"></label><label class="field"><span>Dificuldade TRI oficial</span><select id="p3-sim-tri"><option value="">Mista · todas as faixas</option>'+['Fácil','Média','Difícil','sem dado'].map(t=>'<option>'+t+'</option>').join('')+'</select></label><label class="field"><span>Tempo total (minutos)</span><input id="p3-sim-minutes" type="number" min="1" max="1440" value="60"></label></div>'+AREAS.filter(a=>a.id!=='redacao').map(a=>'<details class="p3-area-select" '+(a.id==='matematica'?'open':'')+'><summary>'+a.name+' <small>'+p3Subjects.filter(s=>s.area===a.id).length+' matérias</small></summary>'+p3Subjects.filter(s=>s.area===a.id).map(s=>'<div class="p3-subject-row" data-subject-key="'+esc(s.key)+'"><label class="p3-check"><input type="checkbox" data-sim-check><b>'+esc(s.subject)+'</b></label><label class="field"><span>Quantidade</span><input type="number" min="1" max="180" value="5" data-sim-count></label><label class="field"><span>Assuntos · seleção múltipla opcional</span><select multiple size="3" data-sim-topics aria-label="Assuntos de '+esc(s.subject)+'">'+p3Topics.filter(t=>t.area===s.area&&t.subject===s.subject).map(t=>'<option value="'+esc(t.topic)+'">'+esc(t.topic)+' ('+t.count+')</option>').join('')+'</select></label><span data-available></span></div>').join('')+'</details>').join('')+'<div class="p3-builder-bottom"><b id="p3-sim-total">0 selecionadas</b><button type="submit" class="btn primary">Gerar e iniciar simulado</button></div><div id="p3-builder-error" role="alert"></div></form></section><section class="panel"><h2>Meu histórico <small>'+sessions.length+' / '+P3_MAX+'</small></h2><p>Até 40 sessões, sem apagar automaticamente as anteriores. Refazer cria uma nova sessão com as mesmas questões, preservando o resultado original. Exportar backup inclui simulados e plano.</p><div class="p3-history">'+(sessions.length?sessions.map(s=>{const c=s.results.filter(r=>r.choice===r.answer).length;return '<article class="p3-history-card"><div><span class="eyebrow">'+esc(s.status==='completed'?'CONCLUÍDO':'PAUSADO / EM ANDAMENTO')+'</span><h3>'+esc(s.title)+'</h3><p>'+s.keys.length+' questões · '+p3DateLabel(p3Today(s.createdAt))+'</p><small>'+(s.status==='completed'?c+' acertos · '+p3Duration(s.elapsedMs)+' de treino':'Respostas salvas: '+Object.keys(s.answers).length+' · tempo '+p3Duration(s.elapsedMs))+'</small></div><div class="button-row">'+p3Button(s.status==='completed'?'Ver resultado':'Retomar','open-session','data-id="'+s.id+'"',true)+(s.status==='completed'?p3Button('Refazer','redo-session','data-id="'+s.id+'"'):'')+p3Button('Excluir','delete-session','data-id="'+s.id+'"')+'</div></article>'}).join(''):'<div class="empty"><b>Seu primeiro treino começa aqui.</b><p>Escolha um mini ou personalize as matérias acima.</p></div>')+'</div><div class="button-row">'+btn('Exportar backup completo','export','primary')+btn('Importar backup','import')+'</div></section>';p3Availability()}
 function p3QuestionStem(q,list){let h=questionHTML(q,list);const cut=h.indexOf('<section class="answer-section">');if(cut>=0)h=h.slice(0,cut);return h.replace(/<div class="session-banner">[\s\S]*?<\/div>/,'')}
 function p3RenderActive(){const s=p3Session();if(!s){state.view='simulators';p3RenderSimulators();return}if(s.status==='completed'){state.view='sim-result';p3RenderResult();return}const q=getQ(s.keys[s.index]),a=s.answers[key(q)]||{},answered=Object.values(s.answers).filter(a=>a.choice).length;$('#main').innerHTML=p3Header(s.title,'Seu resultado só aparece ao finalizar. As respostas ficam salvas neste navegador.')+'<section class="panel p3-session-toolbar"><div><span class="eyebrow">TEMPO RESTANTE</span><strong id="p3-clock" role="timer">'+p3Duration(s.limitMs-p3Elapsed(s))+'</strong><small>'+answered+' de '+s.keys.length+' respondidas · '+(s.status==='running'?'cronômetro ativo':'pausado')+'</small></div><div class="button-row">'+p3Button(s.status==='running'?'Pausar':'Retomar','toggle-sim','',true)+p3Button('Finalizar treino','finish-sim')+p3Button('Sair e salvar','exit-sim')+'</div></section><div class="p3-session-layout"><aside class="panel p3-answer-map"><h2>Questões</h2><div>'+s.keys.map((k,i)=>'<button type="button" class="'+(i===s.index?'current ':'')+(s.answers[k]?.choice?'filled':'')+'" data-p3="sim-jump" data-index="'+i+'" aria-label="Questão '+(i+1)+(s.answers[k]?.choice?', respondida':'')+'">'+(i+1)+'</button>').join('')+'</div><p class="method-note">Preenchida = alternativa marcada. A confiança pode ser completada antes de encerrar.</p></aside><section class="panel p3-session-question">'+(s.status==='running'?p3QuestionStem(q,s.keys.map(getQ))+'<section class="p3-sim-answers"><h3>Minha alternativa</h3>'+Array.from('ABCDE').map(l=>'<button type="button" class="alternative '+(a.choice===l?'p3-picked':'')+'" data-p3="sim-choice" data-letter="'+l+'" aria-pressed="'+(a.choice===l)+'"><b>'+l+'</b><span>'+(q.native&&!q.native.flags.length&&q.native.displayMode!=='original'?q.native.alternatives[l]:'Alternativa '+l+' · confira na prova acima')+'</span></button>').join('')+(a.choice?'<section class="confidence-panel"><h3>Como você chegou à alternativa '+a.choice+'?</h3><div class="confidence-options">'+Object.entries(CONF).map(([id,label])=>p3Button(label,'sim-confidence','data-confidence-id="'+id+'" aria-pressed="'+(a.confidence===id)+'"',a.confidence===id)).join('')+'</div></section>':'<p class="muted">Escolha uma alternativa; depois registre Certeza, Dúvida ou Chute.</p>')+'</section>':'<div class="p3-pause-screen"><span>Ⅱ</span><h2>Uma pausa de verdade.</h2><p>O enunciado e as alternativas ficam ocultos enquanto o relógio está pausado.</p>'+p3Button('Retomar meu simulado','toggle-sim','',true)+'</div>')+'<div class="question-navigation">'+p3Button('← Anterior','sim-move','data-delta="-1" '+(s.index===0?'disabled':''))+p3Button('Próxima / pular →','sim-move','data-delta="1" '+(s.index===s.keys.length-1?'disabled':''))+'</div></section></div><p class="method-note">Sair desta tela ou fechar normalmente pausa o tempo. Após um fechamento inesperado, a retomada usa o último registro (até 10 segundos de diferença). O limite encerra o treino automaticamente.</p>';clearInterval(p3Clock);if(s.status==='running'){if(p3Elapsed(s)>=s.limitMs){p3Finish(s,'tempo');return}let ticks=0;p3Clock=setInterval(()=>{if(state.view!=='simulator'||!s.runningAt)return;if($('#p3-clock'))$('#p3-clock').textContent=p3Duration(s.limitMs-p3Elapsed(s));if(p3Elapsed(s)>=s.limitMs){p3Finish(s,'tempo');toast('Tempo encerrado. Seu resultado foi salvo.')}else if(++ticks%10===0)p3Checkpoint(s)},1000)}}
 function p3Bars(groups){return groups.map(g=>'<div class="stat-row"><div class="bar-label"><span>'+esc(g.label)+'</span><b>'+g.pct+'%</b></div><div class="bar-track"><span style="width:'+g.pct+'%"></span></div><small>'+g.correct+' acertos em '+g.total+' itens · '+(g.total-g.answered)+' em branco'+(g.answered<3?' · amostra pequena':'')+'</small></div>').join('')}
 function p3SuggestionCards(source){const list=p3Plan.suggestions.filter(x=>x.status==='pending'&&(!source||x.source===source));return '<section class="panel p3-suggestions"><h2>Próximos passos concretos</h2><p>Propostas, nunca mudanças automáticas. Precisamos de pelo menos 3 respostas por assunto para sugerir reforço. A amostra não mede domínio completo.</p>'+(list.length?list.map(s=>{const t=p3Topics.find(t=>t.key===s.topicKey);return '<article class="p3-suggestion"><span class="eyebrow">'+esc(t?.subject)+'</span><h3>'+esc(t?.topic)+'</h3><p>'+esc(s.evidence)+'. '+(s.errorType?'Erro mais indicado: '+ERRORS[s.errorType]+'. ':'')+'Reserve dois blocos para resolver, corrigir e refazer questões, sem aumentar sua carga horária.</p>'+p3Button('Ver horários antes de aceitar','preview-suggestion','data-id="'+s.id+'"',true)+'</article>'}).join(''):'<p class="muted">Sem nova proposta com amostra suficiente. Continue praticando; não vamos inventar pontos fracos.</p>')+'<div id="p3-proposal-preview"></div></section>'}
 function p3RenderResult(){const s=p3Session();if(!s?.results?.length){state.view='simulators';p3RenderSimulators();return}const rows=s.results,c=rows.filter(r=>r.choice===r.answer).length,blank=rows.filter(r=>!r.choice).length,topics=p3Groups(rows,r=>topicKey(r.area,r.subject,r.topic)),strong=topics.filter(g=>g.answered>=3&&g.answeredPct>=80),weak=topics.filter(g=>g.answered>=3&&g.answeredPct<60),detail=rows[Math.max(0,Math.min(rows.length-1,state.simDetail))],q=getQ(detail.key);$('#main').innerHTML=p3Header('Resultado do simulado',esc(s.title)+' · fotografia desta sessão, sem alterar resultados anteriores.')+'<section class="quick-stats"><div><span>ACERTOS</span><strong>'+c+' / '+rows.length+'</strong><small>'+Math.round(c/rows.length*100)+'% do total de itens</small></div><div><span>EM BRANCO</span><strong>'+blank+'</strong><small>não entram como acerto</small></div><div><span>TEMPO DE TREINO</span><strong>'+p3Duration(s.elapsedMs)+'</strong><small>'+(s.finishReason==='tempo'?'limite encerrado':'finalizado por você')+'</small></div></section><div class="button-row p3-space">'+p3Button('← Histórico','sim-home')+p3Button('Refazer mesmas questões','redo-session','data-id="'+s.id+'"',true)+'<button class="btn secondary" data-view="plan">Meu plano</button></div><div class="performance-grid"><section class="panel"><h2>Pontos fortes nesta amostra</h2>'+(strong.length?strong.map(g=>'<p><b>'+esc(p3Topics.find(t=>t.key===g.label)?.topic||g.label)+'</b> · '+g.correct+'/'+g.answered+' respostas corretas</p>').join(''):'<p>Sem assunto com pelo menos 3 respostas e 80% de acerto. Isso não significa ausência de pontos fortes.</p>')+'</section><section class="panel"><h2>Vale reforçar</h2>'+(weak.length?weak.map(g=>'<p><b>'+esc(p3Topics.find(t=>t.key===g.label)?.topic||g.label)+'</b> · '+g.correct+'/'+g.answered+' respostas corretas</p>').join(''):'<p>Sem recorte abaixo de 60% com pelo menos 3 respostas. Amostras pequenas pedem mais prática, não conclusões.</p>')+'</section></div><div class="performance-grid"><section class="panel"><h2>Por matéria</h2>'+p3Bars(p3Groups(rows,r=>p3AreaName(r.area)+' · '+r.subject))+'</section><section class="panel"><h2>Por dificuldade TRI oficial</h2>'+p3Bars(p3Groups(rows,'tri'))+'</section></div><details class="panel p3-space"><summary><b>Por assunto / submatéria</b></summary>'+p3Bars(topics.map(g=>({...g,label:p3Topics.find(t=>t.key===g.label)?.topic||g.label})))+'</details><div class="performance-grid"><section class="panel"><h2>Por confiança</h2>'+p3Bars(p3Groups(rows,r=>CONF[r.confidence]||'Não informada'))+'</section><section class="panel"><h2>Tipos de erro</h2>'+Object.entries({...ERRORS,unknown:'Não classificado'}).map(([id,label])=>'<div class="count-row"><span>'+label+'</span><b>'+rows.filter(r=>r.choice&&r.choice!==r.answer&&(id==='unknown'?!r.errorType:r.errorType===id)).length+'</b></div>').join('')+'<p class="method-note">Classifique cada erro na revisão abaixo. É sua observação, não diagnóstico automático.</p></section></div><details class="panel p3-experimental"><summary>Estimativa experimental — NÃO é nota ENEM/INEP</summary><p><b>Não é uma previsão de nota nem de aprovação.</b> b sozinho não reproduz a TRI. Abaixo há somente um modelo didático por área, sem calibração/validação contra o ENEM.</p>'+AREAS.filter(a=>a.id!=='redacao'&&rows.some(r=>r.area===a.id)).map(a=>{const z=p3Proxy(rows.filter(r=>r.area===a.id));return '<p><b>'+a.name+':</b> '+(z.available?'≈ '+z.value+' na escala editorial · '+z.n+' itens com b oficial':esc(z.reason))+'</p>'}).join('')+'<details><summary>Fórmula e limitações</summary><p>Para cada área, maximizamos uma verossimilhança em θ entre −4 e 4, com P(acerto)=0,2+0,8/(1+exp(−(θ−b))). A discriminação 1 e o piso 0,2 são hipóteses editoriais, NÃO parâmetros A/C oficiais. A transformação 500+100θ, arredondada em 25, não tem equivalência comprovada com a escala INEP. Branco conta como erro. Exigimos 10 respostas/itens com b; padrões extremos e estimativas no limite não geram número. Confiança/tipo de erro não entram na fórmula. Não misturamos áreas.</p></details></details>'+p3SuggestionCards(s.id)+'<section class="panel p3-result-review"><h2>Revisar as questões deste treino</h2><label class="field"><span>Questão</span><select id="p3-result-select">'+rows.map((r,i)=>'<option value="'+i+'" '+(i===state.simDetail?'selected':'')+'>'+(i+1)+' · '+getQ(r.key).id+' · '+(r.choice?(r.choice===r.answer?'Acertou':'Errou'):'Em branco')+' · '+esc(r.topic)+'</option>').join('')+'</select></label>'+p3QuestionStem(q,s.keys.map(getQ))+'<div class="p3-result-alternatives">'+Array.from('ABCDE').map(l=>'<div class="alternative '+(l===detail.answer?'is-correct':l===detail.choice?'is-wrong':'')+'"><b>'+l+'</b><span>'+(q.native&&!q.native.flags.length&&q.native.displayMode!=='original'?q.native.alternatives[l]:'Alternativa '+l+' · confira no original acima')+'</span><b>'+(l===detail.answer?'✓ Correta':l===detail.choice?'× Marcada':'')+'</b></div>').join('')+'</div><div class="feedback '+(detail.choice===detail.answer?'success':'error')+'"><div><h3>'+(detail.choice===detail.answer?'Resposta correta':'Vamos entender este item')+'</h3><p>Marcada: '+(detail.choice||'em branco')+' · Gabarito: '+detail.answer+' · Confiança: '+(CONF[detail.confidence]||'não informada')+'</p><p>'+esc(q.comment)+'</p><small>Comentário original da apostila. O piloto de resoluções detalhadas alternativa a alternativa fica para a próxima entrega.</small></div></div>'+(detail.choice&&detail.choice!==detail.answer?'<div class="error-analysis"><h3>O que pesou neste erro?</h3><div class="button-row">'+Object.entries(ERRORS).map(([id,label])=>p3Button(label,'result-error','data-error="'+id+'"',detail.errorType===id)).join('')+'</div><p>'+esc({conteudo:'Veja uma explicação curta, feche o material e resolva novas questões do conceito.',interpretacao:'Releia o comando e anote a evidência que diferencia a correta do distrator.',distracao:'Refaça conferindo sinais, unidades, contas e palavras de restrição.'}[detail.errorType]||'Sua classificação ajuda a escolher o próximo passo.')+'</p></div>':'')+'<p class="online-note">A busca precisa de internet; a numeração pode variar conforme o caderno da prova.</p><div class="button-row">'+external(youtubeURL(q),'Buscar resolução no YouTube')+p3Button('Praticar este assunto no banco','practice-topic','data-topic-key="'+esc(topicKey(q.area,q.subject,q.topic))+'"')+'</div></section>'}
 function p3DayChecks(name,selected=[]){return p3Days.map((d,i)=>'<label class="p3-daycheck"><input type="checkbox" name="'+name+'" value="'+i+'" '+(selected.includes(i)?'checked':'')+'>'+d.slice(0,3)+'</label>').join('')}
 function p3WindowHTML(w=[810,960]){return '<div class="p3-window"><label class="field"><span>Início</span><input type="time" data-window-start value="'+p3HH(w[0])+'"></label><label class="field"><span>Fim</span><input type="time" data-window-end value="'+p3HH(w[1])+'"></label>'+p3Button('Remover janela','remove-row')+'</div>'}
 function p3CommitmentHTML(c={title:'',days:[],start:840,end:900}){return '<div class="p3-commitment p3-entry"><label class="field"><span>Compromisso</span><input data-commit-title value="'+esc(c.title)+'" placeholder="Ex.: curso, esporte, transporte" maxlength="80"></label><div class="p3-daychecks">'+p3DayChecks('commit-days',c.days)+'</div><div class="p3-form-grid"><label class="field"><span>Início</span><input type="time" data-commit-start value="'+p3HH(c.start)+'"></label><label class="field"><span>Fim</span><input type="time" data-commit-end value="'+p3HH(c.end)+'"></label>'+p3Button('Remover compromisso','remove-row')+'</div></div>'}
 function p3ExamHTML(e={date:'',subjectKey:'',topic:'',start:null,end:null}){return '<div class="p3-exam p3-entry"><div class="p3-form-grid"><label class="field"><span>Data da prova</span><input type="date" data-exam-date value="'+esc(e.date)+'"></label><label class="field"><span>Matéria</span><select data-exam-subject><option value="">Escolha</option>'+p3Subjects.map(s=>'<option value="'+esc(s.key)+'" '+(s.key===e.subjectKey?'selected':'')+'>'+p3AreaName(s.area)+' · '+esc(s.subject)+'</option>').join('')+'<option value="redacao|Redação" '+(e.subjectKey==='redacao|Redação'?'selected':'')+'>Redação</option></select></label><label class="field"><span>Assunto (opcional)</span><input data-exam-topic value="'+esc(e.topic||'')+'" placeholder="Use o nome do assunto do banco"></label><label class="field"><span>Horário de início (opcional)</span><input type="time" data-exam-start value="'+(e.start!=null?p3HH(e.start):'')+'"></label><label class="field"><span>Horário de fim (se informar início)</span><input type="time" data-exam-end value="'+(e.end!=null?p3HH(e.end):'')+'"></label></div>'+p3Button('Remover prova','remove-row')+'</div>'}
 function p3PlanBuilderHTML(){const p=p3Plan.profile||state.v3ExampleDraft||p3DefaultProfile();return '<section class="panel p3-plan-builder"><h2>Minha rotina real</h2><p>Não sabemos seus horários. Os horários desativados são apenas exemplos; ative e ajuste os dias disponíveis. A grade só nasce quando você confirma. Todos os horários: <b>America/Sao_Paulo (BRT, UTC−3)</b>.</p><form id="p3-plan-form"><div class="p3-form-grid"><label class="field"><span>Início do plano</span><input type="date" id="p3-plan-start" value="'+p.start+'"></label><label class="field"><span>Horizonte (não é data oficial ENEM)</span><input type="date" id="p3-plan-end" max="2027-11-30" value="'+p.end+'"></label><label class="field"><span>Bloco de estudo (min)</span><input type="number" min="15" max="90" id="p3-plan-block" value="'+p.block+'"></label><label class="field"><span>Pausa entre blocos (min)</span><input type="number" min="0" max="20" id="p3-plan-break" value="'+p.break+'"></label></div><h3>Escola — tempo ocupado</h3><label class="p3-check"><input type="checkbox" id="p3-school-enabled" '+(p.school.enabled?'checked':'')+'>Bloquear estes horários da escola</label><div class="p3-daychecks">'+p3DayChecks('p3-school-day',p.school.days)+'</div><div class="p3-form-grid"><label class="field"><span>Entrada</span><input type="time" id="p3-school-start" value="'+p3HH(p.school.start)+'"></label><label class="field"><span>Saída</span><input type="time" id="p3-school-end" value="'+p3HH(p.school.end)+'"></label></div><p class="method-note">Se a escola tiver horários diferentes em cada dia, use os compromissos fixos por dia. Inclua deslocamento/descanso se precisar. A escola é descontada das janelas, nunca sobreposta por estudo.</p><h3>Quando eu realmente posso estudar</h3><p>Limite diário inclui pausas. Janelas sobrepostas são unidas; tempos ocupados são subtraídos. Não preenchemos madrugada nem criamos horas extras.</p>'+[1,2,3,4,5,6,0].map(day=>{const d=p.weekly[day];return '<fieldset class="p3-weekday" data-weekday="'+day+'"><legend><label class="p3-check"><input type="checkbox" data-day-enabled '+(d.enabled?'checked':'')+'>'+p3Days[day]+'</label></legend><label class="field p3-budget"><span>Limite diário (min, com pausas)</span><input type="number" min="0" max="720" data-day-budget value="'+d.budget+'"></label><div data-day-windows>'+d.windows.map(p3WindowHTML).join('')+'</div>'+p3Button('+ Outra janela neste dia','add-window','data-day="'+day+'"')+'</fieldset>'}).join('')+'<h3>Outros compromissos fixos</h3><div id="p3-commitments">'+p.commitments.map(p3CommitmentHTML).join('')+'</div>'+p3Button('+ Compromisso semanal','add-commitment')+'<h3>Provas escolares e datas próximas</h3><p>Informe a data e a matéria. Nos 7 dias anteriores, a matéria ganha prioridade editorial; se você informar horário da prova, ele também fica bloqueado. Não presumimos quais provas você tem.</p><div id="p3-exams">'+p.exams.map(p3ExamHTML).join('')+'</div>'+p3Button('+ Prova / avaliação','add-exam')+'<h3>Redação toda semana</h3><div class="p3-form-grid"><label class="field"><span>Meta semanal (min; 0 desativa)</span><input type="number" min="0" max="180" step="5" id="p3-red-minutes" value="'+p.redMinutes+'"></label><label class="field"><span>Dia preferido</span><select id="p3-red-day">'+p3Days.map((d,i)=>'<option value="'+i+'" '+(i===p.redDay?'selected':'')+'>'+d+'</option>').join('')+'</select></label></div><h3>Ponto de partida — editável</h3><p>Notas opcionais, informadas por você; não são diagnóstico de capacidade. Deixe em branco para usar prioridade neutra por área. Junto da frequência dos assuntos no seu banco e do desempenho com amostra suficiente, entram numa heurística de prioridades.</p><div class="p3-form-grid">'+['linguagens','humanas','natureza','matematica','redacao'].map(a=>'<label class="field"><span>'+p3AreaName(a)+'</span><input data-score="'+a+'" type="number" min="0" max="1000" value="'+(p.scores[a]??'')+'"></label>').join('')+'</div><aside class="p3-practice-first"><b>Mais questões, menos cópia.</b> Fora a redação e as pausas, pelo menos 60% do tempo de cada bloco gerado é de prática/recuperação; na maioria dos blocos é 100%. Videoaula curta serve para destravar. Essa distribuição é editorial e ajustável, não uma proporção científica universal.</aside><p class="method-note">Fases editoriais: Base até março/2027; Aprofundamento de abril a agosto; Revisão de setembro a novembro. 30/11/2027 é horizonte provisório, não a data oficial da prova. A meta de redação pode ocupar blocos em outros dias se não couber no preferido.</p><div class="button-row"><button type="submit" class="btn primary">'+(p3Plan.profile?'Atualizar minha rotina e grade':'Gerar meu plano personalizado')+'</button><button class="btn secondary" type="button" data-view="methods">Como estudar cada matéria</button></div><div id="p3-plan-error" role="alert"></div></form></section>'}
 function p3ReadProfile(){const previous=p3Plan.profile,p=p3DefaultProfile();p.start=$('#p3-plan-start').value;p.end=$('#p3-plan-end').value;p.block=Number($('#p3-plan-block').value);p.break=Number($('#p3-plan-break').value);p.redMinutes=Number($('#p3-red-minutes').value);p.redDay=Number($('#p3-red-day').value);p.school={enabled:$('#p3-school-enabled').checked,days:$$('[name=p3-school-day]:checked').map(x=>Number(x.value)),start:p3Minutes($('#p3-school-start').value),end:p3Minutes($('#p3-school-end').value)};p.weekly=Array.from({length:7},(_,day)=>{const row=$('[data-weekday="'+day+'"]');return{day,enabled:row.querySelector('[data-day-enabled]').checked,budget:Number(row.querySelector('[data-day-budget]').value),windows:Array.from(row.querySelectorAll('.p3-window')).map(w=>[p3Minutes(w.querySelector('[data-window-start]').value),p3Minutes(w.querySelector('[data-window-end]').value)])}});p.commitments=$$('.p3-commitment').map(row=>({title:row.querySelector('[data-commit-title]').value.slice(0,80)||'Compromisso fixo',days:Array.from(row.querySelectorAll('[name=commit-days]:checked')).map(x=>Number(x.value)),start:p3Minutes(row.querySelector('[data-commit-start]').value),end:p3Minutes(row.querySelector('[data-commit-end]').value)}));p.exams=$$('.p3-exam').map(row=>({date:row.querySelector('[data-exam-date]').value,subjectKey:row.querySelector('[data-exam-subject]').value,topic:row.querySelector('[data-exam-topic]').value.trim().slice(0,200),start:row.querySelector('[data-exam-start]').value?p3Minutes(row.querySelector('[data-exam-start]').value):null,end:row.querySelector('[data-exam-end]').value?p3Minutes(row.querySelector('[data-exam-end]').value):null}));for(const el of $$('[data-score]'))p.scores[el.dataset.score]=Number(el.value);p3ValidateProfile(p);p.weights=p3Weights(p);p.updatedAt=Date.now();return p}
 function p3AgendaHTML(){const p=p3Plan.profile;if(!p)return'<section class="panel empty"><h2>Seu plano precisa da sua rotina.</h2><p>Não vamos inventar horários. Preencha escola, compromissos e disponibilidade primeiro.</p>'+p3Button('Configurar minha rotina','plan-tab','data-tab="builder"',true)+'</section>';const schedule=p3Schedule(),start=state.planRange==='month'?state.planDate.slice(0,7)+'-01':p3Monday(state.planDate),end=state.planRange==='month'?p3Add(p3ISO(new Date(Date.UTC(Number(start.slice(0,4)),Number(start.slice(5,7)),1))),-1):p3Add(start,6),slots=schedule.slots.filter(s=>s.date>=start&&s.date<=end),study=slots.filter(s=>s.kind!=='break'),minutes=study.reduce((n,s)=>n+s.end-s.start,0),practice=study.flatMap(p3Segments).filter(s=>['questions','review'].includes(s.type)).reduce((n,s)=>n+s.end-s.start,0),done=study.filter(s=>p3Plan.done[s.id]).length,warnings=schedule.warnings.filter(x=>x.slice(0,10)>=start&&x.slice(0,10)<=end);return'<section class="panel p3-agenda-controls p3-no-print"><div class="p3-form-grid"><label class="field"><span>Ir para a data</span><input type="date" id="p3-plan-date" min="'+p.start+'" max="'+p.end+'" value="'+state.planDate+'"></label><label class="field"><span>Visualizar</span><select id="p3-plan-range"><option value="week" '+(state.planRange==='week'?'selected':'')+'>Semana</option><option value="month" '+(state.planRange==='month'?'selected':'')+'>Mês</option></select></label><div class="button-row">'+p3Button('← Anterior','plan-period','data-delta="-1"')+p3Button('Próximo →','plan-period','data-delta="1"')+p3Button('Imprimir esta grade','print-plan','',true)+'</div></div></section><div class="p3-agenda-title"><h2>'+p3DateLabel(start)+' a '+p3DateLabel(end)+'</h2><p>America/Sao_Paulo (BRT, UTC−3) · '+minutes+' min de estudo/escrita · '+practice+' min de prática/recuperação · '+done+'/'+study.length+' blocos concluídos</p><small>“Concluído” é marcado por você. Pausas não entram nos minutos de estudo; meta de questões é flexível. Videoaulas usam tempo reservado, não duração de um vídeo específico.</small></div>'+(warnings.length?'<aside class="native-warning"><b>Ajustes de capacidade</b><ul>'+warnings.map(w=>'<li>'+esc(w)+'</li>').join('')+'</ul></aside>':'')+'<div class="p3-agenda">'+Array.from({length:Math.round((p3Date(end)-p3Date(start))/86400000)+1},(_,i)=>p3Add(start,i)).filter(d=>d>=p.start&&d<=p.end).map(date=>{const day=slots.filter(s=>s.date===date);return'<section class="p3-day panel"><header><div><h3>'+p3Days[p3Day(date)]+' · '+p3DateLabel(date)+'</h3><small>'+p3Phase(date)+' · horários BRT (UTC−3)</small></div><span>'+day.filter(s=>s.kind!=='break').length+' blocos</span></header>'+(day.length?day.map(s=>{if(s.kind==='break')return'<div class="p3-break"><time>'+p3HH(s.start)+'–'+p3HH(s.end)+'</time><span>Pausa · '+(s.end-s.start)+' min</span></div>';const finished=!!p3Plan.done[s.id],cancelled=!!s.cancelled;return'<article class="p3-slot '+(finished?'is-done ':'')+(cancelled?'is-cancelled':'')+'"><div class="p3-slot-top"><label class="p3-check p3-no-print"><input type="checkbox" data-p3-done="'+s.id+'" '+(finished?'checked':'')+' aria-label="Concluir bloco '+p3HH(s.start)+' de '+esc(s.subject)+'"></label><time>'+p3HH(s.start)+'–'+p3HH(s.end)+'</time><b>'+esc(s.subject)+'</b><span>'+esc(s.topic)+'</span>'+(finished?'<strong>✓ Concluído</strong>':'')+'</div>'+(cancelled?'<p>Bloco dispensado por você.</p>':p3Segments(s).map(seg=>'<div class="p3-segment"><time>'+p3HH(seg.start)+'–'+p3HH(seg.end)+'</time><div><p>'+esc(seg.title)+'</p>'+(seg.type==='video'?'<a target="_blank" rel="noopener noreferrer" href="'+esc((seg.teacher?.url||'https://www.youtube.com')+'/search?query='+encodeURIComponent(s.subject+' '+s.topic))+'">Buscar aula deste assunto no canal ↗</a><small>Internet necessária; escolha uma aula pertinente. Não verificamos a duração de cada vídeo da busca.</small>':seg.type==='redacao'?p3Button('Abrir tema da semana','write-theme','data-theme="'+s.themeId+'"'):seg.type==='review'?p3Button('Abrir caderno de erros','review-from-plan')+p3Button('Questões deste assunto','practice-topic','data-topic-key="'+esc(topicKey(s.area,s.subject,s.topic))+'"'):p3Button('Praticar no banco','practice-topic','data-topic-key="'+esc(topicKey(s.area,s.subject,s.topic))+'"'))+'</div></div>').join(''))+'<div class="p3-slot-actions p3-no-print">'+p3Button('Editar bloco','edit-slot','data-slot="'+s.id+'" '+(finished?'disabled':''))+p3Button(cancelled?'Restaurar bloco':'Dispensar este bloco','skip-slot','data-slot="'+s.id+'" '+(finished?'disabled':''))+'</div><div id="p3-edit-'+s.id.replace('@','-')+'"></div></article>'}).join(''):'<p class="muted">Sem estudo planejado. Descanso e compromissos também fazem parte da rotina.</p>')+'</section>'}).join('')+'</div><p class="method-note">A sequência de horários é calculada a partir da rotina salva; não são eventos de calendário e não há lembretes fora do site. Ajustar a rotina exige confirmação. Resultados novos só alteram blocos por proposta aceita.</p>'}
 function p3RenderPlan(){const profile=p3Plan.profile;if(!profile&&state.planTab==='agenda')state.planTab='builder';$('#main').innerHTML=p3Header('Meu plano · ENEM 2027','Uma rotina possível, com muitas questões e espaço para escola, pausas e redação.')+'<div class="p3-tabs p3-no-print">'+[['agenda','Minha grade'],['builder','Rotina e horários'],['suggestions','Sugestões'],['method','Métodos e evidências']].map(([id,label])=>p3Button(label,'plan-tab','data-tab="'+id+'"',state.planTab===id)).join('')+'</div>'+(state.planTab==='builder'?p3PlanBuilderHTML():state.planTab==='suggestions'?p3SuggestionCards()+'<section class="panel"><h2>Alterações aceitas</h2>'+p3Plan.accepted.slice().reverse().map(x=>'<p>'+esc(p3Topics.find(t=>t.key===p3Plan.suggestions.find(s=>s.id===x.id)?.topicKey)?.topic||'Prática direcionada')+' · '+p3Button('Desfazer alterações ainda não concluídas','undo-suggestion','data-id="'+x.id+'"')+'</p>').join('')+'</section>':state.planTab==='method'?p3MethodsHTML():p3AgendaHTML());}
 function p3MethodsHTML(){return'<section class="panel p3-method-intro"><h2>Menos copiar, mais recuperar e aplicar</h2><p>O resumo é um apoio para uma dúvida concreta. Você não precisa terminar resumos de um assunto para começar suas questões. Use lotes pequenos e frequentes, explique o raciocínio e retome o erro em outro dia.</p><p>A agenda reserva no máximo 40% de alguns blocos para uma aula curta; os demais priorizam questões, recuperação e correção. Redação ocupa tempo próprio de produção. Tempos, metas e fases são heurísticas editoriais editáveis, não promessas científicas.</p></section>'+[['Matemática','matematica'],['Física','natureza'],['Química','natureza'],['Biologia','natureza'],['História','humanas'],['Geografia','humanas'],['Filosofia','humanas'],['Sociologia','humanas'],['Linguagens e Inglês','linguagens'],['Redação','redacao']].map(([s,a])=>p3MethodHTML(s,a,true)).join('')+'<section class="panel p3-evidence"><h2>O que a pesquisa sustenta — e o que não garante</h2><article><h3>Prática de teste e prática distribuída</h3><p>Dunlosky et al. (2013) classificam essas técnicas como de alta utilidade em diversos materiais e contextos. Autoexplicação e intercalamento receberam utilidade moderada. Resumir, reler ou grifar isoladamente têm benefícios mais limitados/condicionais; isso não significa que nunca ajudem.</p><a href="https://pubmed.ncbi.nlm.nih.gov/26173288/" target="_blank" rel="noopener noreferrer">Dunlosky et al. (2013), registro e resumo ↗</a></article><article><h3>Espaçamento depende do objetivo de retenção</h3><p>Cepeda et al. (2006) sintetizaram estudos de recordação verbal. O intervalo de estudo e o tempo até o teste atuam em conjunto; não existe uma agenda única ótima para todos. O ciclo 1/3/7/15 do caderno é uma escolha editorial, não uma prescrição literal desse artigo.</p><a href="https://www.yorku.ca/ncepeda/publications/CPVWR2006.html" target="_blank" rel="noopener noreferrer">Cepeda et al. (2006), página do autor ↗</a></article><article><h3>Tentar lembrar também ensina</h3><p>Nos experimentos de Roediger e Karpicke (2006), testes de recuperação de textos favoreceram retenção tardia comparados à releitura. Aqui aplicamos o princípio a perguntas e justificativas, sem afirmar que o efeito ou o tamanho dele é idêntico em toda matéria do ENEM.</p><a href="https://www.psychologicalscience.org/journals/psychological-science/j.1467-9280.2006.01693.x/" target="_blank" rel="noopener noreferrer">Roediger & Karpicke (2006), resumo do artigo ↗</a></article><article><h3>Pomodoro e autoexplicação</h3><p>Francesco Cirillo propõe organizar foco, pausas, planejamento e reflexão. Blocos de 25/5 são um ponto de partida ajustável, não uma superioridade universal demonstrada. Explicar como se estivesse ensinando (às vezes chamado Feynman) é uma orientação de autoexplicação; não atribuímos uma garantia científica específica ao nome.</p><a href="https://www.pomodorotechnique.com/" target="_blank" rel="noopener noreferrer">Fonte do método Pomodoro ↗</a></article><h3>Vídeos de apoio sobre como estudar</h3><ul><li><a href="https://www.youtube.com/watch?v=pEunw5aKMYc" target="_blank" rel="noopener noreferrer">Como fazer estudo espaçado ↗</a> — exemplo de distribuir o mesmo tempo por vários dias.</li><li><a href="https://www.youtube.com/watch?v=O96fE1E-rf8" target="_blank" rel="noopener noreferrer">Learning how to learn · Barbara Oakley ↗</a> — em inglês; organização, recuperação e prática, com metáforas de divulgação.</li></ul><p class="method-note">Links conferidos em 10/11/2026. Abertura requer internet. Vídeos são divulgação, não substituem as fontes de pesquisa nem endossamos toda generalização dos palestrantes. Nada é baixado ou incorporado.</p></section>'}
 function p3RenderMethods(){$('#main').innerHTML=p3Header('Como estudar cada matéria','Métodos diferentes, prática frequente e evidências com limites explícitos.')+p3MethodsHTML()}
 function p3ShowProposal(id){const s=p3Plan.suggestions.find(s=>s.id===id),target=$('#p3-proposal-preview');if(!target||!s)return;if(!p3Plan.profile){target.innerHTML='<aside class="native-warning"><b>Primeiro, informe sua rotina.</b><p>Não criamos horas de estudo sem saber sua disponibilidade.</p><button class="btn primary" data-view="plan">Configurar Meu plano</button></aside>';return}const changes=p3PreviewSuggestion(id);target.innerHTML='<section class="p3-proposal"><h3>Prévia da mudança — horários BRT (UTC−3)</h3><p>Troca somente o conteúdo de dois blocos ainda não editados/concluídos nos próximos 14 dias. Não altera escola, compromissos, pausas, duração nem outros horários.</p>'+(changes.length===2?'<ul>'+changes.map(c=>'<li><b>'+p3DateLabel(c.before.date)+' · '+p3HH(c.before.start)+'–'+p3HH(c.before.end)+'</b><br>Antes: '+esc(c.before.subject+' · '+c.before.topic)+'<br>Depois: '+esc(c.after.subject+' · '+c.after.topic)+' · prática direcionada</li>').join('')+'</ul>'+p3Button('Aceitar estas duas mudanças','accept-suggestion','data-id="'+id+'"',true):'<p>Não há dois blocos livres/editáveis nesse período. Ajuste sua rotina se quiser abrir espaço; não acrescentamos horas automaticamente.</p>')+'</section>';target.scrollIntoView?.({block:'nearest',behavior:'smooth'})}
 function p3PracticeTopic(k){const t=p3Topics.find(t=>t.key===k);if(!t)throw Error('Assunto não encontrado.');p3Pause();state.diagnostic=null;state.pending=null;state.reviewKey=null;state.area=t.area;state.filters={subject:t.subject,topic:t.topic,year:'',tri:'',status:'all',search:''};const qs=p3Pool(t),q=qs.find(q=>!record(q)?.choice)||qs[0];if(record(q)?.choice)state.retry.add(key(q));state.qid=q.id;state.view='bank';nav();renderBank(q.id);window.scrollTo?.(0,0)}
 function p3ShowSlotEditor(id){const s=p3Schedule().slots.find(s=>s.id===id),target=document.getElementById('p3-edit-'+id.replace('@','-'));if(!s||!target||p3Plan.done[id])return;target.innerHTML='<form class="p3-slot-editor" data-slot-editor="'+id+'"><h4>Editar bloco de '+p3DateLabel(s.date)+' · BRT (UTC−3)</h4><div class="p3-form-grid"><label class="field"><span>Início</span><input type="time" name="start" value="'+p3HH(s.start)+'" required></label><label class="field"><span>Fim</span><input type="time" name="end" value="'+p3HH(s.end)+'" required></label><label class="field"><span>Atividade personalizada (opcional)</span><input name="title" maxlength="240" value="'+esc(s.customTitle||'')+'" placeholder="Ex.: resolver 4 questões e corrigir"></label></div><p>O dia, a matéria e o assunto permanecem. Para redistribuir matérias, use uma proposta ou atualize a rotina. Não aceitamos sobreposição com escola, compromissos, outros blocos ou pausas.</p><button type="submit" class="btn primary">Salvar edição</button>'+p3Button('Cancelar','cancel-edit','data-slot="'+id+'"')+'<div class="p3-inline-error" role="alert"></div></form>';target.scrollIntoView?.({block:'nearest',behavior:'smooth'})}
