const p3bResolutions=new Map((window.ENEM_RESOLUTIONS||[]).map(r=>[r.key,r])),p3bLazyIndex=window.ENEM_RESOLUTION_INDEX||{},p3bLoads=new Map(),p3bLoadErrors=new Map();
function p3bEnsure(file,retry=false){
 if(!/^data\/resolucoes\/[a-z]+_20(?:21|22|23|24|25)\.js$/.test(file||''))return Promise.resolve(false);
 if(p3bLoads.has(file)&&!retry)return p3bLoads.get(file);
 p3bLoadErrors.delete(file);
 const promise=new Promise(resolve=>{const script=document.createElement('script');script.src=file;script.dataset.resolutionChunk=file;
 script.onload=()=>{try{const records=window.ENEM_RESOLUTION_CHUNKS?.[file];if(!Array.isArray(records)||!records.length)throw Error('Pacote vazio');const expected=Object.values(p3bLazyIndex).filter(r=>r.lazyFile===file);if(records.length!==expected.length||new Set(records.map(r=>r.key)).size!==expected.length)throw Error('Pacote incompleto');for(const r of records){const q=getQ(r.key),meta=p3bLazyIndex[r.key];if(!q||meta?.lazyFile!==file||r.answer!==q.answer||r.year!==q.year||r.number!==q.number||r.area!==q.area||r.year<2021||r.year>2025||r.status!=='verified'||!r.provenance?.verified||!Array.isArray(r.steps)||r.steps.length<3||!Array.from('ABCDE').every(l=>typeof r.alternatives?.[l]==='string'&&r.alternatives[l].length>35))throw Error('Conferência do pacote falhou')}for(const r of records)p3bResolutions.set(r.key,r);resolve(true)}catch(e){p3bLoadErrors.set(file,'Pacote inválido');p3bLoads.delete(file);resolve(false)}render()};
 script.onerror=()=>{p3bLoadErrors.set(file,'Arquivo indisponível');p3bLoads.delete(file);script.remove();resolve(false);render()};document.head.appendChild(script)});p3bLoads.set(file,promise);return promise;
}
