 function v3VideoResults(query,subject){const C=window.ENEM_CHANNELS||[],by=new Map(C.map(c=>[c.id,c])),tokens=norm(query).trim().split(/\s+/).filter(Boolean),groups=tokens.map(t=>v3Synonyms.find(g=>g.includes(t))||[t]);return(window.ENEM_VIDEO_INDEX?.videos||[]).map(v=>{const c=by.get(v.channelId),t=norm(v.title+' '+(v.description||'')+' '+(c?.name||''));if(!c||(subject&&!c.subjects.includes(subject)&&!c.subjects.includes('Multidisciplinar'))||!groups.every(g=>g.some(w=>t.includes(w))))return null;const score=(tokens.length&&norm(v.title).includes(norm(query).trim())?20:0)+(c.favorite?100:0)+(c.chosen?5:0);return{v,c,score}}).filter(Boolean).sort((a,b)=>b.score-a.score||a.c.order-b.c.order)}
 const v3Teachers=renderVideos;renderVideos=function(){v3Teachers();const C=window.ENEM_CHANNELS||[],subjects=[...new Set(C.flatMap(c=>c.subjects))].sort(),query=state.videoSearch||'';if(state.v3PrevQuery!==query+'|'+state.videoSubject){state.v3PrevQuery=query+'|'+state.videoSubject;state.v3VideoLimit=24}if(state.v3VideoTab==='channels'){$('.video-filters')?.insertAdjacentHTML('beforebegin','<div class="p3-tabs"><button class="btn secondary" data-v3-video-tab="videos">Buscar videoaulas</button><button class="btn primary" data-v3-video-tab="channels">Canais e professores</button></div>');return}v3LoadVideos();const result=v3VideoResults(query,state.videoSubject||''),meta=window.ENEM_VIDEO_INDEX?.meta;$('#main').innerHTML='<header class="page-heading"><div><span class="eyebrow">UMA DÚVIDA, UMA AULA, DEPOIS QUESTÕES</span><h1>Aulas no YouTube</h1><p>Busque um assunto e escolha uma videoaula específica dos canais da curadoria.</p></div><span class="online-pill">Busca e miniaturas offline · assistir requer internet</span></header><div class="p3-tabs"><button class="btn primary" data-v3-video-tab="videos">Buscar videoaulas</button><button class="btn secondary" data-v3-video-tab="channels">Canais e professores</button></div><section class="filter-panel video-filters"><label class="field"><span>Assunto ou professor</span><input id="video-search" type="search" placeholder="Ex.: ecologia, porcentagem, Noslen…" value="'+esc(query)+'"></label><label class="field"><span>Matéria do canal</span><select id="video-subject"><option value="">Todas as matérias</option>'+subjects.map(s=>'<option '+(state.videoSubject===s?'selected':'')+'>'+esc(s)+'</option>').join('')+'</select></label></section><p class="method-note">'+(meta?fmt(meta.count)+' vídeos indexados · até 300 uploads recentes por canal (não exaustivo). Busca por títulos, metadados disponíveis e sinônimos; prioridade aos favoritos entre resultados compatíveis.':'Carregando o índice local de vídeos…')+' Não há vídeo incorporado, download de aula nem chamada de IA. Os links abrem o YouTube.</p><p aria-live="polite" id="v3-video-count">'+(meta?fmt(result.length)+' videoaulas encontradas':'')+'</p><section class="v3-video-grid">'+(meta?result.slice(0,state.v3VideoLimit||24).map(({v,c})=>'<article class="v3-video-card"><a target="_blank" rel="noopener noreferrer" href="https://www.youtube.com/watch?v='+v.id+'" aria-label="Assistir: '+esc(v.title)+'"><svg class="v3-video-thumb" role="img" aria-label="Miniatura da videoaula" viewBox="'+v.sprite.x+' '+v.sprite.y+' 96 54"><image href="'+esc(v.thumbnail)+'" width="'+v.sprite.width+'" height="'+v.sprite.height+'"/></svg><div>'+(c.favorite?'<span class="favorite-label">♥ FAVORITO</span>':'')+'<h2>'+esc(v.title)+'</h2><p>'+esc(c.name)+'</p><small>'+(v.duration?Math.ceil(v.duration/60)+' min · ':'')+'Abrir vídeo ↗</small></div></a></article>').join(''):v3VideoError?'<section class="panel"><h2>Índice local não encontrado</h2><p>Confira se data/videos.js está na mesma pasta do site. Os canais continuam disponíveis na outra aba.</p></section>':'<p>Preparando a busca…</p>')+'</section>'+(meta&&result.length>(state.v3VideoLimit||24)?'<button type="button" class="btn secondary" data-v3-more-videos>Mostrar mais 24</button>':'')+(meta&&!result.length?'<section class="panel empty"><h2>Nenhum título neste recorte</h2><p>Tente um termo mais curto, um sinônimo ou outro filtro. O catálogo não inclui todo o histórico dos canais.</p></section>':'');decorateView()};
